제가 몇달 전에 오늘의 집 집들이를 구경하다가 정말 마음에 드는 커튼을 발견했는데요, 
일단 기억나는것
1. 흰색바탕에 검은색 포인트 무늬가 불규칙하게 패턴처럼 들어갔다
