--------------------------------------------------------
--  DDL for Trigger TRIG_PRODUCT_IO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "ADMIN"."TRIG_PRODUCT_IO" 
        before
        insert on product_io
        for each row
begin
          -- 입고 시
          if :new.status = 'I' then
                  update
                        product_stock
                  set
                        stock = stock + :new.count
                  where
                        product_id = :new.product_id;
           -- 출고 시              
          else
                 update
                        product_stock
                  set
                        stock = stock - :new.count
                  where
                        product_id = :new.product_id;
         end if;
end;

/
ALTER TRIGGER "ADMIN"."TRIG_PRODUCT_IO" ENABLE;
